```javascript
function switchAdjectiveOrder(sentence) {
  const regex = /^([A-Z][^\s]+ [Article]\s+[Adjective][\s]*[Noun]\s+.*)$/; // Regex pattern for the given sentence structure
  const match = regex.exec(sentence);

  if (!match) {
    throw new Error("Invalid sentence structure");
  }

  const [, , adjective, rest] = match;
  const newSentence = `${sentence.slice(0, sentence.indexOf(adjective))}${rest.replace(/(?<=\s)[A-Z]/g, ` ${adjective} ${RegExp.$1}`)}`;

  return newSentence;
}

const Article = ["the", "a", "an"];
const Adjective = ["green", "beautiful"];

const originalSentence = "Beautiful green trees are in the park";
const result = switchAdjectiveOrder(originalSentence);
console.log(result); // Output: "Green beautiful trees are in the park"
```

