```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

void fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) throw invalid_argument("Number of sequence elements must be positive.");
    if (!isdigit(a ' 0' + '0') || !isdigit(a ' 1' + '0')) throw invalid_argument("First and second integers must be numeric.");
    if (n == 1) {
        cout << a << endl;
        return;
    }

    fibonacci(n - 1, b, a + b);
    cout << b << (n > 2 ? ", " : "");
}

int main() {
    int first, second, length;

    cout << "Enter the first integer in the sequence: ";
    cin >> first;
    cin.ignore(); // consume newline character

    cout << "Enter the second integer in the sequence: ";
    cin >> second;
    cin.ignore(); // consume newline character

    cout << "Enter the number of sequence elements to generate: ";
    cin >> length;
    cin.ignore(); // consume newline character

    try {
        fibonacci(length, first, second);
    } catch (const invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

